"""Independent higher-precision checks are scoped numerical evidence only."""

import copy
import hashlib
import json
from pathlib import Path

import mpmath as mp
import pytest

from experiments.check_census import (
    _batched_lu_solve,
    check_census,
    check_held_out_cross,
    check_selected_cores,
    panel_samples,
    strictest_records,
)
from kernelgecp.grids import composite_chebyshev_grids


def _record(rank: int = 2) -> dict:
    """Analytically specified small cores, not generated by the census runner."""
    with mp.workprec(160):
        a = 1 / (1 + mp.e)
        b = mp.e / (1 + mp.e)
        determinant = a * a - b * b
        sigma = a + b if rank == 1 else abs(a - b)
        return {
            "schema_version": 2,
            "cutoff": "1",
            "tolerance": "1e-12",
            "precision_bits": 128,
            "rank": rank,
            "residual": ["1", "0.8", "1e-13"][rank],
            "residual_history": ["1", "0.8", "1e-13"][: rank + 1],
            "t_nodes": ["0", "1"][:rank],
            "omega_nodes": ["-1", "1"][:rank],
            "pivots": [mp.nstr(a, 45), mp.nstr(determinant / a, 45)][:rank],
            "core_det_history": [mp.nstr(a, 45), mp.nstr(determinant, 45)][:rank],
            "core_sigma_min": [mp.nstr(a, 45), mp.nstr(sigma, 45)][:rank],
            "metadata": {"configuration": {"grid_order": 4}},
        }


def test_independent_selected_cores_check_signed_determinant_and_svd() -> None:
    report = check_selected_cores(_record())
    assert report["status"] == "passed"
    assert [case["rank"] for case in report["checks"]] == [1, 2]
    with mp.workprec(192):
        for case in report["checks"]:
            assert mp.mpf(case["stored_determinant_relative_error"]) < mp.mpf("1e-40")
            assert mp.mpf(case["signed_pivot_product_relative_error"]) < mp.mpf("1e-40")
            assert mp.mpf(case["stored_sigma_relative_error"]) < mp.mpf("1e-40")
        assert mp.mpf(report["checks"][-1]["determinant"]) < 0


def test_core_disagreement_is_flagged_without_relaxing_tolerance() -> None:
    record = _record()
    record["core_det_history"][-1] = "-0.1"
    record["core_sigma_min"][-1] = "0.1"
    report = check_selected_cores(record)
    assert report["status"] == "disagreement"
    assert report["checks"][-1]["status"] == "disagreement"
    assert report["checks"][0]["status"] == "passed"


def test_rank_zero_has_no_core_or_factorization_and_zero_ratio_is_explicit() -> None:
    record = _record(0)
    assert check_selected_cores(record)["status"] == "not_applicable_rank_zero"
    record["residual"] = "0"
    record["residual_history"] = ["0"]
    held_out = check_held_out_cross(record, denser_order=8)
    assert held_out["solve_method"] == "not_applicable_rank_zero"
    assert held_out["solve_relative_max_entry_residual"] is None
    assert held_out["ratio_to_source_terminal_residual"] is None
    assert held_out["ratio_status"] == "undefined_source_zero"
    assert held_out["exceeds_source_terminal_residual"]
    assert not held_out["within_requested_tolerance_on_sample"]


def test_batched_factorization_matches_independent_vector_solves() -> None:
    with mp.workprec(192):
        core = mp.matrix([[0, 2], [3, 4]])
        rhs = mp.matrix([[1, 2, 3], [4, 5, 6]])
        observed = _batched_lu_solve(core, rhs)
        for column in range(rhs.cols):
            reference = mp.lu_solve(core, rhs[:, column])
            assert max(
                abs(observed[i, column] - reference[i]) for i in range(2)
            ) < mp.mpf("1e-55")


def test_held_out_sample_is_every_panel_and_not_on_source_axes() -> None:
    times, frequencies, policy = panel_samples(1_000_000, 24)
    source_t, source_w = composite_chebyshev_grids(1_000_000, 24)
    assert not set(map(float, times)).intersection(source_t)
    assert not set(map(float, frequencies)).intersection(source_w)
    assert len(times) == 3 * policy["panel_counts"][0]
    assert len(frequencies) == 3 * policy["panel_counts"][1]
    assert all(count == 3 for axis in policy["samples_per_panel"] for count in axis)
    assert policy["sample_count"] == len(times) * len(frequencies)
    assert times == panel_samples(1_000_000, 24)[0]
    assert policy["coordinate_precision_bits"] == 53


def test_batched_solve_handles_noninvolutive_lu_permutation() -> None:
    with mp.workprec(192):
        core = mp.matrix([[0, 0, 2], [4, 0, 3], [1, 5, 6]])
        rhs = mp.matrix([[1, 2], [3, 4], [5, 6]])
        permutation, lower, upper = mp.lu(core)
        assert permutation != permutation.T
        assert mp.norm(permutation * core - lower * upper) == 0
        solution = _batched_lu_solve(core, rhs)
        assert mp.norm(core * solution - rhs) < mp.mpf("1e-55")
        for column in range(rhs.cols):
            expected = mp.lu_solve(core, rhs[:, column])
            assert mp.norm(solution[:, column] - expected) < mp.mpf("1e-55")


def test_held_out_residual_is_an_observation_not_a_denser_gecp_claim() -> None:
    report = check_held_out_cross(_record(), denser_order=8)
    assert report["certification_status"] == "not_certified"
    assert report["scope"] == "stored_selected_cross_on_panel_spanning_held_out_sample"
    assert report["not_claimed"] == [
        "denser_GECP_run",
        "full_denser_grid_max",
        "continuous_bound",
    ]
    assert not report["within_requested_tolerance_on_sample"]
    assert report["exceeds_source_terminal_residual"]
    with mp.workprec(192):
        assert mp.mpf(report["held_out_max_abs_residual"]) > mp.mpf("1e-4")
        assert mp.mpf(report["solve_relative_max_entry_residual"]) < mp.mpf("1e-55")


def test_full_report_is_byte_reproducible_and_binds_input(tmp_path: Path) -> None:
    path = tmp_path / "small.jsonl"
    path.write_text(json.dumps(_record()) + "\n", encoding="utf-8")
    first = check_census(path, denser_order=8)
    second = check_census(path, denser_order=8)
    assert json.dumps(first, sort_keys=True, allow_nan=False) == json.dumps(
        second, sort_keys=True, allow_nan=False
    )
    assert first["input_sha256"] == hashlib.sha256(path.read_bytes()).hexdigest()
    assert first["strictest_trajectory_count"] == 1
    assert first["status"] == "passed_numerical_core_checks"
    assert first["unavailable_representative_cutoffs"] == ["1000", "1000000"]
    assert first["certification_status"] == "not_certified"


def test_compatible_prefixes_select_strictest_case() -> None:
    loose = _record(1)
    loose["tolerance"] = "0.9"
    strict = _record(2)
    assert strictest_records([loose, strict]) == [strict]
    wrong = copy.deepcopy(loose)
    wrong["residual_history"][0] = "0.9"
    with pytest.raises(ValueError, match="incompatible prefix"):
        strictest_records([wrong, strict])
    with pytest.raises(ValueError, match="duplicate cutoff/tolerance"):
        strictest_records([strict, copy.deepcopy(strict)])


@pytest.mark.parametrize(
    ("field", "value", "message"),
    [
        ("schema_version", 1, "schema_version"),
        ("rank", True, "rank must be an integer"),
        ("precision_bits", 52, "precision_bits"),
        ("cutoff", "Infinity", "finite"),
        ("cutoff", "1e1000", "representable"),
        ("tolerance", "0", "tolerance"),
        ("residual_history", ["1"], "misaligned"),
        ("core_det_history", ["1", "NaN"], "finite"),
        ("pivots", ["1", "0"], "nonzero"),
        ("core_sigma_min", ["1", "-1"], "positive"),
        ("t_nodes", ["0", "2"], "lie in"),
        ("omega_nodes", ["0", "2"], "outside"),
        ("t_nodes", ["0", "0.0"], "distinct"),
        ("residual", "0", "terminal residual"),
    ],
)
def test_invalid_histories_and_nonfinite_inputs_are_rejected(
    field: str, value, message: str
) -> None:
    record = _record()
    record[field] = value
    with pytest.raises(ValueError, match=message):
        check_selected_cores(record)


def test_check_precision_must_exceed_source_and_denser_order_must_increase() -> None:
    with pytest.raises(ValueError, match="exceed source"):
        check_selected_cores(_record(), precision_bits=128)
    with pytest.raises(ValueError, match="exceed source"):
        check_held_out_cross(_record(), precision_bits=128)
    with pytest.raises(ValueError, match="denser_order"):
        check_held_out_cross(_record(), denser_order=4)
    with pytest.raises(ValueError, match="at least one record"):
        strictest_records([])


def test_held_out_requires_recorded_source_grid_order() -> None:
    record = _record()
    record["metadata"] = None
    with pytest.raises(ValueError, match="source configuration"):
        check_held_out_cross(record)
    record["metadata"] = {"configuration": {}}
    with pytest.raises(ValueError, match="source grid_order"):
        check_held_out_cross(record)
